d=df.copy(); d['first']=d.number_set.str.split(',').str[0].astype(int); d['last']=d.number_set.str.split(',').str[-1].astype(int); d['n']=d.number_set.str.count(',')+1
print(d.groupby('n').rating.agg(['mean','count']))
print(np.corrcoef(d.trial_index,d.rating))
